"use client";
import { useState } from "react";
import Image from "next/image";
import { shimmer } from "@/components/utils/shimmer";

const toBase64 = (str: string) =>
  typeof window === "undefined"
    ? Buffer.from(str).toString("base64")
    : window.btoa(str);

export default function ImageCarousel({
  images,
  children,
}: {
  images: any;
  children: React.ReactNode;
}) {
  const carouselImages: { imageUrl: string }[] = images
    .map((item: any) => {
      const url = item.high || item.main;
      if (!url) return null;
      return {
        imageUrl: url.replace(
          "tsgroup.s3.amazonaws.com",
          "d2lpxiu1sq3srq.cloudfront.net"
        ),
      };
    })
    .filter(Boolean);

  const [active, setActive] = useState(0);
  const total = carouselImages.length;

  if (total === 0) return <div>{children}</div>;

  const navBtn =
    "tw-absolute tw-top-1/2 tw--translate-y-1/2 tw-bg-black/40 hover:tw-bg-black/60 tw-text-white tw-rounded-full tw-w-9 tw-h-9 tw-flex tw-items-center tw-justify-center tw-transition-colors tw-border-0 tw-cursor-pointer";

  return (
    <div>
      <div className="md:tw-float-right md:tw-w-1/2 tw-w-full tw-mb-3 md:tw-ml-3">
        <div className="tw-relative tw-rounded tw-overflow-hidden">
          <Image
            key={active}
            src={carouselImages[active].imageUrl}
            alt={`Image ${active + 1}`}
            width={750}
            height={500}
            className="tw-block tw-w-full tw-h-auto"
            quality={100}
            loading="lazy"
            placeholder={`data:image/svg+xml;base64,${toBase64(
              shimmer(750, 500)
            )}`}
          />

          {total > 1 && (
            <>
              <button
                type="button"
                onClick={() => setActive((a) => (a - 1 + total) % total)}
                className={`${navBtn} tw-left-3`}
                aria-label="Previous"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
                  <path fillRule="evenodd" d="M11.354 1.646a.5.5 0 0 1 0 .708L5.707 8l5.647 5.646a.5.5 0 0 1-.708.708l-6-6a.5.5 0 0 1 0-.708l6-6a.5.5 0 0 1 .708 0z" />
                </svg>
              </button>
              <button
                type="button"
                onClick={() => setActive((a) => (a + 1) % total)}
                className={`${navBtn} tw-right-3`}
                aria-label="Next"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
                  <path fillRule="evenodd" d="M4.646 1.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1 0 .708l-6 6a.5.5 0 0 1-.708-.708L10.293 8 4.646 2.354a.5.5 0 0 1 0-.708z" />
                </svg>
              </button>

              <div className="tw-absolute tw-bottom-3 tw-left-1/2 tw--translate-x-1/2 tw-flex tw-gap-1.5">
                {carouselImages.map((_, i) => (
                  <button
                    key={i}
                    type="button"
                    onClick={() => setActive(i)}
                    aria-label={`Go to image ${i + 1}`}
                    className={`tw-h-2 tw-rounded-full tw-border-0 tw-cursor-pointer tw-transition-all ${
                      i === active
                        ? "tw-w-5 tw-bg-white"
                        : "tw-w-2 tw-bg-white/60"
                    }`}
                  />
                ))}
              </div>
            </>
          )}
        </div>
      </div>
      <div>{children}</div>
      <div style={{ clear: "both" }} />
    </div>
  );
}
